import foodsJson from './foods.json';

// Generated by data/food-db/build_nutrition.py — edit the source data there, not foods.json.

export type Diet = 'veg' | 'egg' | 'non_veg';

export interface Nutrition {
  kcal: number;
  protein_g: number;
  carbs_g: number;
  fat_g: number;
  fiber_g: number;
  sugars_g: number;
  sodium_mg: number;
}

export interface Food {
  id: string;
  name: string;
  category: string;
  cuisine: string;
  diet: Diet;
  portionUnit: string;
  portionGrams: number;
  visualGroup: string;
  per100g: Nutrition;
}

export interface PortionOption {
  quantity: number; // multiples of the food's standard portion
  label: string;
}

const FOODS = foodsJson as Food[];
const FOODS_BY_ID = new Map(FOODS.map((food) => [food.id, food]));

export const getFood = (id: string) => FOODS_BY_ID.get(id);

const normalize = (text: string) => text.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();

const SEARCH_INDEX = FOODS.map((food) => ({
  food,
  name: normalize(food.name),
  words: normalize(food.name).split(' '),
  extra: normalize(`${food.id} ${food.cuisine} ${food.category}`),
}));

// Ranks name prefix > word prefix > substring > cuisine/category match.
export const searchFoods = (query: string, limit = 6): Food[] => {
  const q = normalize(query);
  if (!q) {
    return [];
  }

  return SEARCH_INDEX.map((entry) => {
    let score = 0;
    if (entry.name.startsWith(q)) score = 4;
    else if (entry.words.some((word) => word.startsWith(q))) score = 3;
    else if (entry.name.includes(q)) score = 2;
    else if (entry.extra.includes(q)) score = 1;
    return { food: entry.food, score };
  })
    .filter((result) => result.score > 0)
    .sort((a, b) => b.score - a.score || a.food.name.length - b.food.name.length)
    .slice(0, limit)
    .map((result) => result.food);
};

// Units that are naturally counted ("2 rotis") rather than scaled ("1½ katori")
const COUNTABLE_UNITS = new Set(['piece', 'slice', 'scoop', 'cup', 'glass', 'tbsp', 'handful']);

const UNIT_LABELS: Record<string, [singular: string, plural: string]> = {
  piece: ['piece', 'pieces'],
  slice: ['slice', 'slices'],
  scoop: ['scoop', 'scoops'],
  cup: ['cup', 'cups'],
  glass: ['glass', 'glasses'],
  tbsp: ['tbsp', 'tbsp'],
  handful: ['handful', 'handfuls'],
  katori: ['katori', 'katoris'],
  bowl: ['bowl', 'bowls'],
  plate: ['plate', 'plates'],
  half: ['half', 'halves'],
  medium: ['medium', 'medium'],
  '6_inch': ['6-inch', '6-inch'],
};

const formatQuantity = (quantity: number) =>
  quantity === 0.5 ? '½' : Number.isInteger(quantity) ? `${quantity}` : `${Math.floor(quantity)}½`;

export const portionLabel = (food: Food, quantity: number) => {
  const [singular, plural] = UNIT_LABELS[food.portionUnit] ?? [food.portionUnit, food.portionUnit];
  return `${formatQuantity(quantity)} ${quantity > 1 ? plural : singular}`;
};

export const portionOptions = (food: Food): PortionOption[] => {
  const quantities = COUNTABLE_UNITS.has(food.portionUnit) ? [1, 2, 3, 4, 6] : [0.5, 1, 1.5, 2];
  return quantities.map((quantity) => ({ quantity, label: portionLabel(food, quantity) }));
};

export const nutritionFor = (food: Food, grams: number): Nutrition => {
  const scale = grams / 100;
  const per100g = food.per100g;
  return {
    kcal: per100g.kcal * scale,
    protein_g: per100g.protein_g * scale,
    carbs_g: per100g.carbs_g * scale,
    fat_g: per100g.fat_g * scale,
    fiber_g: per100g.fiber_g * scale,
    sugars_g: per100g.sugars_g * scale,
    sodium_mg: per100g.sodium_mg * scale,
  };
};
